      setColor(colorCode) {
        this.restyle((s) => ({ ...s, c: colorCode === '7' ? '' : colorCode }));
      },
      toggleFormat(flag) {
        const on = !this.formatActive(flag);
        this.restyle((s) => ({ ...s, [flag]: on }));
      },
      clearFormatting() {
        this.restyle(() => plain());
      },

      /** Advanced: the exact text that is saved, with § codes. */
      editCodes(event) {
