          this.notice = t('too_long', { max: MAX });
          event.target.value = this.written;
          return;
        }
        this.value = value;
        this.load(value);
        this.written = value;
      },

      editorRuns(index) {
        return runs(this.lines[index] || { chars: [], styles: [] });
      },
      scroll(index, event) {
        const mirror = this.$refs?.['mirror' + index];
        if (mirror) mirror.scrollLeft = event.target.scrollLeft;
      },
